#!/usr/bin/env bash
# Start the isolated benchmark stack: generated .env (gitignored, random secrets), infra/compose/bootstrap.sh
# with the bench overlay, two extra worker credentials, pg_stat_statements. Workers are left stopped.
set -euo pipefail
. "$(dirname "$0")/env.sh"
rand() { openssl rand -hex 24; }
if [ ! -f "$ROOT/.env" ]; then
  umask 077
  cat > "$ROOT/.env" <<E
# clusterx-bench (generated by scripts/bench/up.sh; scripts/bench/down.sh deletes it)
POSTGRES_PASSWORD=$(rand)
CLUSTERX_APP_DB_PASSWORD=$(rand)
CLUSTERX_METRICS_TOKEN=$(rand)
CLUSTERX_PG_PORT=${CLUSTERX_PG_PORT:-55461}
CLUSTERX_HTTP_PORT=${CLUSTERX_HTTP_PORT:-18091}
CLUSTERX_METRICS_PORT=${CLUSTERX_METRICS_PORT:-19291}
CLUSTERX_PROMETHEUS_PORT=${CLUSTERX_PROMETHEUS_PORT:-19391}
CLUSTERX_IMAGE_PREFIX=${CLUSTERX_IMAGE_PREFIX:-clusterx-m8}
E
fi
grep -q '^# clusterx-bench' "$ROOT/.env" || { echo "$ROOT/.env was not generated by up.sh; use a dedicated checkout" >&2; exit 1; }
for i in 4 5; do [ -e .secrets/worker_credential_$i ] || { mkdir -p .secrets; : > .secrets/worker_credential_$i; }; done
./bootstrap.sh
for i in 4 5; do
  if [ ! -s .secrets/worker_credential_$i ]; then
    dc run --rm --no-deps control-plane worker-credential create --name worker-$i | sed -n 's/^secret=//p' | tr -d '\n' > .secrets/worker_credential_$i
    [ -s .secrets/worker_credential_$i ] || { echo "credential $i failed" >&2; exit 1; }
    chmod 644 .secrets/worker_credential_$i
  fi
done
psqlq -c 'CREATE EXTENSION IF NOT EXISTS pg_stat_statements'
dc --profile workers stop "${ALL_WORKERS[@]}" >/dev/null 2>&1 || true
echo "bench stack up: project=$COMPOSE_PROJECT_NAME api=http://127.0.0.1:$(envval CLUSTERX_HTTP_PORT)"
